/*
 * Non-Secure Callable (NSC) API exported by the Secure world.
 *
 * Shared by both images: the Secure build defines these functions with
 * CMSE_NS_ENTRY, the Non-Secure build links against the veneers in
 * secure_nsclib.o generated by the Secure link (--cmse-implib).
 */
#ifndef SECURE_NSC_H
#define SECURE_NSC_H

#include <stdint.h>

#define SECURE_MAC_SIZE  32U   /* HMAC-SHA256 tag length in bytes */

typedef enum
{
  SECURE_OK            = 0,
  SECURE_ERR_PARAM     = 1,   /* NULL pointer or buffer not fully Non-Secure */
  SECURE_ERR_MAC       = 2,   /* MAC verification failed */
  SECURE_ERR_SELFTEST  = 3,   /* known-answer test failed */
  SECURE_ERR_INTERNAL  = 4
} secure_status_t;

/* Provided by system_stm32l5xx_s.c (ST template). */
uint32_t SECURE_SystemCoreClockUpdate(void);

/* M1: trivial Secure service, proves the NS -> S -> NS round trip. */
uint32_t SECURE_Add(uint32_t a, uint32_t b);

/* Number of SECURE_Add calls; the counter itself lives in Secure SRAM. */
uint32_t SECURE_GetCallCount(void);

/* M3: empty Secure function; measures the bare NS -> S -> NS transition cost. */
void SECURE_Nop(void);

/* M2: crypto service. The device key never leaves the Secure world. */

/* Run the RFC 4231 HMAC-SHA256 known-answer tests inside the Secure world. */
secure_status_t SECURE_CryptoSelfTest(void);

/* mac = HMAC-SHA256(device_key, msg[0..len)). Both buffers must be Non-Secure. */
secure_status_t SECURE_MAC_Compute(const uint8_t *msg, uint32_t len,
                                   uint8_t mac[SECURE_MAC_SIZE]);

/* Constant-time check of mac against HMAC-SHA256(device_key, msg). */
secure_status_t SECURE_MAC_Verify(const uint8_t *msg, uint32_t len,
                                  const uint8_t mac[SECURE_MAC_SIZE]);

/* M4: measurement-only probes. Each adds one step of SECURE_MAC_Compute:
 * argument passing, pointer checks. */
secure_status_t SECURE_Probe_Args(const uint8_t *msg, uint32_t len,
                                  uint8_t mac[SECURE_MAC_SIZE]);
secure_status_t SECURE_Probe_Checks(const uint8_t *msg, uint32_t len,
                                    uint8_t mac[SECURE_MAC_SIZE]);

/* Cycles of hmac_sha256() alone, timed inside the Secure world (0 on error). */
uint32_t SECURE_Probe_HmacCycles(const uint8_t *msg, uint32_t len,
                                 uint8_t mac[SECURE_MAC_SIZE]);

/* SECURE_MAC_Compute with each step timed inside the Secure world:
 * steps[] = cycles for pointer checks, HMAC, copy-out, zeroize, and the
 * former mbedtls_platform_zeroize on a same-size buffer (comparison only). */
#define SECURE_PROBE_STEPS  5U
secure_status_t SECURE_Probe_MacSteps(const uint8_t *msg, uint32_t len,
                                      uint8_t mac[SECURE_MAC_SIZE],
                                      uint32_t steps[SECURE_PROBE_STEPS]);

#endif /* SECURE_NSC_H */
